const themeDefault4835='#ff4632', themeKey4835='momentum.accent.v1';
let themeValue4835=themeDefault4835;try{themeValue4835=localStorage.getItem(themeKey4835)||themeDefault4835}catch(e){}
function themeHsl4835(hex){let [r,g,b]=[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min,l=(max+min)/2,h=0,s=0;if(d){s=d/(1-Math.abs(2*l-1));h=(max===r?(g-b)/d:max===g?(b-r)/d+2:(r-g)/d+4)*60}return [(h+360)%360,s,l]}
function themeTint4835(hex){if(themeValue4835===themeDefault4835)return '#'+hex;let [h,s,l]=themeHsl4835(hex),[ah,as,al]=themeHsl4835(themeValue4835.slice(1)),[bh]=themeHsl4835('ff4632');let hue=(h+ah-bh+360)%360, sat=Math.min(1,s*(.45+.55*as)),light=Math.max(0,Math.min(1,l+(al-.598)*Math.min(1,l*2)));let a=hex.length===8?parseInt(hex.slice(6),16)/255:1;return `hsla(${hue},${sat*100}%,${light*100}%,${a})`}
function applyTheme4835(v,persist=false){if(!/^#[0-9a-f]{6}$/i.test(v))v=themeDefault4835;themeValue4835=v.toLowerCase();let root=document.documentElement;for(let [k,h] of Object.entries(themePalette4835))root.style.setProperty(k,themeTint4835(h));for(let [name,svg] of Object.entries(themeArt4835)){let art=svg.replace(/#[0-9a-f]{6}\b/gi,m=>{let [h,s,l]=themeHsl4835(m.slice(1));return (h<36||h>342)&&l>.13?themeTint4835(m.slice(1)):m});root.style.setProperty('--art-light-'+name.split('.')[0],`url("data:image/svg+xml,${encodeURIComponent(art.replace(/<rect\b[^>]*fill="(?:#09090b|#101012|#0b0b0d|url\(#g\))"[^>]*\/>/gi,''))}")`);root.style.setProperty('--art-theme-'+name.split('.')[0],`url("data:image/svg+xml,${encodeURIComponent(art)}")`)}if(persist)try{localStorage.setItem(themeKey4835,themeValue4835)}catch(e){} }
applyTheme4835(themeValue4835);
function installTheme4835(){const prev=render;render=function(){prev();if(page==='Settings'){let el=document.createElement('section');el.className='card appearance4835';el.innerHTML=`<h3>Appearance</h3><p>Choose your accent colour.</p><div class="themechoices4835">${[['Red','#ff4632'],['Orange','#ff902e'],['Gold','#e6b83e'],['Green','#32c978'],['Teal','#20bdb5'],['Blue','#418bff'],['Purple','#9560ed'],['Pink','#ed589b']].map(([n,c])=>`<button type="button" aria-label="${n}" title="${n}" data-color="${c}" style="--swatch:${c}" aria-pressed="${themeValue4835===c}"></button>`).join('')}</div><div class="line"><label>Custom colour <input type="color" value="${themeValue4835}" aria-label="Custom accent colour"></label><button type="button" class="reset4835">Reset to default</button></div>`;let update=v=>{applyTheme4835(v,true);el.querySelector('input').value=themeValue4835;el.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===themeValue4835)))};el.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>update(b.dataset.color));el.querySelector('input').oninput=e=>update(e.target.value);el.querySelector('.reset4835').onclick=()=>update(themeDefault4835);$('view').append(el)}};render()}
